package org.example.idf_service.service;
import org.example.idf_service.domain.*; import org.example.idf_service.dto.*; import org.example.idf_service.repository.LimitRepository; import org.junit.jupiter.api.*; import java.math.*; import java.time.*; import static org.assertj.core.api.Assertions.*; import static org.mockito.Mockito.*;
class LimitServiceTest { @Test void createsLimitAtClockTime(){ LimitRepository repo=mock(LimitRepository.class); Clock clock=Clock.fixed(Instant.parse("2026-01-10T08:00:00Z"),ZoneOffset.UTC); when(repo.save(any())).thenAnswer(i->i.getArgument(0)); LimitResponse result=new LimitService(repo,clock).create(new LimitRequest("0000000123",ExpenseCategory.PRODUCT,new BigDecimal("500.00"))); assertThat(result.limit_datetime()).isEqualTo(OffsetDateTime.parse("2026-01-10T08:00:00Z")); assertThat(result.limit_sum()).isEqualByComparingTo("500.00"); } }
